// Run:  node scripts/list-images.js
// Scans /images and writes js/images.js so the static site knows what's there.
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const dir = path.join(root, "images");
const exts = /\.(jpe?g|png|gif|webp|avif|mp4|webm|mov)$/i;

const files = fs.existsSync(dir)
  ? fs.readdirSync(dir).filter((f) => exts.test(f)).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }))
  : [];

const out =
  "// AUTO-GENERATED by scripts/list-images.js — don't edit by hand\n" +
  "window.PEPLA_IMAGES = " + JSON.stringify(files, null, 2) + ";\n";

fs.writeFileSync(path.join(root, "js", "images.js"), out);
console.log(`Listed ${files.length} files in js/images.js`);
